import { DOCUMENT } from '@angular/common';
import { DestroyRef, inject, Injectable, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Router } from '@angular/router';
import { EMPTY, fromEvent } from 'rxjs';
import { delay, filter } from 'rxjs/operators';
import { HudState } from '../hud/hud-state';
import { MatchmakerService } from '../net/matchmaker.service';
import { OnlineMatchService } from '../net/online-match.service';
import type { InviteOffer } from '../social/social-notices.component';
import {
  ChallengeView,
  FriendView,
  SocialService,
} from '../social/social.service';
import { GameStateService } from '../state/game-state.service';
import { GameStateStore } from '../state/game.states';
import { pickMatchLevel } from '@wolsok/feat-shared-bacteria-engine';
import { PlayFlow } from './play-flow';

/**
 * Online play on the stage, and what links bring in: hosting and joining a
 * match, a friend's challenge, the matchmaking's matches, the host's starts
 * the guest follows, and the shared run or the invitation a link carries -
 * on the start and whenever a link opens the running game.
 * Provided by the stage component, one per stage; {@link start} sets it
 * going.
 */
@Injectable()
export class OnlineFlow {
  private readonly store = inject(GameStateStore);
  private readonly gameStateService = inject(GameStateService);
  private readonly online = inject(OnlineMatchService);
  private readonly matchmaker = inject(MatchmakerService);
  private readonly social = inject(SocialService);
  private readonly document = inject(DOCUMENT);
  private readonly router = inject(Router);
  private readonly destroyRef = inject(DestroyRef);
  private readonly hud = inject(HudState);
  private readonly flow = inject(PlayFlow);

  /** The lobby of an online match, for the new game's start. */
  public readonly lobby = this.online.lobby;
  public readonly available = this.online.available;
  /** An invitation link opened on this visit, until it is answered. */
  public readonly inviteOffer = signal<InviteOffer | null>(null);
  /**
   * The start of a match that came in while this device still cleared the
   * last one - the host's, or the matchmaking's - played once it is clear.
   */
  private pendingStart: (() => void) | null = null;
  /** True once the stage is gone: a late answer then changes nothing. */
  private gone = false;

  constructor() {
    this.destroyRef.onDestroy(() => (this.gone = true));
  }

  /**
   * Takes what the link brought - a shared run, an invitation - and every
   * link that opens the running game later, and follows the online match's
   * starts from now on.
   */
  public start(): void {
    this.takeLink();
    // A link into the running game - the Android app, an installed PWA's
    // window, an open tab - only changes the hash: no new start reads it.
    // The game's own drop (`dropHash`) replaces the state and fires none.
    // The router syncs with the new address in a task of its own, queued at
    // the popstate before the hashchange; the link is read a task later,
    // so the drop replaces the router's navigation rather than being
    // undone by it.
    const view = this.document.defaultView;
    (view === null ? EMPTY : fromEvent(view, 'hashchange'))
      .pipe(delay(0), takeUntilDestroyed(this.destroyRef))
      .subscribe(() => this.takeLink());
    // The guest of an online match plays what the host starts.
    this.online.events$
      .pipe(
        filter((event) => event.type === 'start'),
        takeUntilDestroyed(this.destroyRef)
      )
      .subscribe(() => this.followOnlineStart());
    // The host of a match the matchmaking set up starts it at once.
    this.online.events$
      .pipe(
        filter(
          (event) =>
            event.type === 'connected' && event.auto && event.seat === 0
        ),
        takeUntilDestroyed(this.destroyRef)
      )
      .subscribe(() => this.startMatchmadeMatch());
    // A start that came in while the arena was cleared plays once it is.
    this.flow.arenaCleared$
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(() => {
        const start = this.pendingStart;
        this.pendingStart = null;
        start?.();
      });
  }

  /** Takes a friend's challenge: on to the online lobby, into their room. */
  public playChallenge(call: ChallengeView): void {
    this.openLobby();
    void this.online.join(call.code);
  }

  /** Challenges a friend from the friends screen: on to the online lobby. */
  public challengeFriend(friend: FriendView): void {
    if (this.lobby().phase !== 'idle') {
      return;
    }
    this.openLobby();
    this.social.challengeFriend(friend);
  }

  /** Opens the new game on the online lobby. */
  private openLobby(): void {
    this.flow.openNewGameOn({ kind: 'online', step: 'start' });
  }

  /** Opens an online match for a friend to join. */
  public host(): void {
    void this.online.host();
  }

  /** Joins a friend's online match under the code they passed on. */
  public join(code: string): void {
    void this.online.join(code);
  }

  /** Leaves the online match, or its lobby. */
  public leave(): void {
    this.gameStateService.leaveOnline();
  }

  /**
   * Starts an automatic online match on the level the matchmaking picked -
   * a random level that plays online if it has none - once the arena is
   * clear, as the reset under way would end the match, and switched only
   * then, so it does not flash up under the dust.
   */
  private startMatchmadeMatch(): void {
    const levelId =
      this.matchmaker.matchLevel()?.levelId ??
      pickMatchLevel(null, null, Math.random).levelId;
    if (this.flow.resetting()) {
      this.pendingStart = () => {
        if (this.store.snapshot().online?.seat === 0) {
          this.gameStateService.setLevel(levelId);
          this.flow.startGame();
        }
      };
      return;
    }
    this.gameStateService.setLevel(levelId);
    this.flow.startGame();
  }

  /**
   * Starts the match the host of an online match started - once the arena
   * is clear: a result on screen is cleared first.
   */
  private followOnlineStart(): void {
    const resetting = this.flow.resetting();
    if (resetting || this.hud.matchOver()) {
      this.pendingStart = () => this.startOnlineMatch();
      if (!resetting) {
        // Not resetGame: that gives the online match up.
        this.flow
          .resetGame$()
          .pipe(takeUntilDestroyed(this.destroyRef))
          .subscribe();
      }
      return;
    }
    this.startOnlineMatch();
  }

  private startOnlineMatch(): void {
    // Not once this device has left - it would start a match of its own.
    if (this.store.snapshot().online?.seat === 1) {
      this.flow.startGame();
    }
  }

  /** Takes the shared run or the invitation the address's hash carries. */
  private takeLink(): void {
    void this.takeChallenge();
    void this.takeInvite();
  }

  /**
   * Takes the run a link carries in its hash as a challenge, and takes it
   * out of the address, so a reload or a bookmark does not offer it again.
   */
  private async takeChallenge(): Promise<void> {
    if (
      !(await this.gameStateService.offerChallenge(this.document.location.hash))
    ) {
      return;
    }
    await this.dropHash();
  }

  /**
   * Takes the invitation a link carries in its hash (`#friend=<token>`)
   * and offers to add the inviter as a friend - and, once it is read,
   * takes it out of the address, so a reload does not offer it again.
   */
  private async takeInvite(): Promise<void> {
    const match = /^#friend=([a-z2-9]{20})$/.exec(this.document.location.hash);
    if (match === null || !this.social.available) {
      return;
    }
    const token = match[1];
    let from: string | null;
    try {
      from = await this.social.readInvite(token);
    } catch {
      // Kept in the address, so a reload reads the invitation again.
      return;
    }
    if (this.gone) {
      return;
    }
    // Only while the address still carries it: the player may have moved on.
    if (this.document.location.hash === match[0]) {
      await this.dropHash();
    }
    if (from !== null) {
      this.inviteOffer.set({ token, from });
    }
  }

  /** Takes the hash out of the address - through the router, which holds it. */
  private async dropHash(): Promise<void> {
    await this.router.navigateByUrl(this.router.url.split('#')[0], {
      replaceUrl: true,
    });
  }
}
import {
  BALANCE_VERSION,
  isInteger,
  isLevelId,
  isObject,
  isRuleset,
  Ruleset,
  TICKS_PER_SEC,
  validColorPair,
} from '@wolsok/feat-shared-bacteria-engine';
import { parseJson } from '@wolsok/utils-json';

/**
 * The version of what two devices say to each other - a new one for every
 * change an older game could not follow. Both sides also need the same
 * balance table, or the same inputs play another match.
 */
export const NET_VERSION = `3/${BALANCE_VERSION}`;

/** What one seat puts in before one tick, on the engine's input grid. */
export interface TickInput {
  /** Where the stick and the keys push - (0, 0) at rest. */
  steer: [x: number, y: number];
  /** Where a finger sent the crosshair since the last tick, if anywhere. */
  drag: [x: number, y: number] | null;
  /** True when the boost was fired since the last tick. */
  boost: boolean;
}

/** The level and colours the host has set up for the next match. */
export interface OnlineSetup {
  levelId: string;
  /** The colour ids of the left (host's) and the right (guest's) colony. */
  colors: [string, string];
}

/** What starts an online match on both devices. */
export interface OnlineStart extends OnlineSetup {
  seed: number;
  /** The ruleset both devices offered - see `agreedRuleset`. */
  ruleset: Ruleset;
}

/**
 * The ruleset of a match between two devices (ADR 0015, decision 6):
 * `gpu-int` when both offer it, `cpu` else - every device can run that, so
 * a match never fails over the ruleset.
 */
export function agreedRuleset(
  own: readonly Ruleset[],
  theirs: readonly Ruleset[]
): Ruleset {
  return own.includes('gpu-int') && theirs.includes('gpu-int')
    ? 'gpu-int'
    : 'cpu';
}

/**
 * Everything that goes over the wire, told apart by `k`. The matches of a
 * connection are numbered (`n`), so what is left of one that was replaced
 * never reaches the next.
 */
export type NetMessage =
  /**
   * The first word each side says: which version of the game it runs, who
   * plays it - their uid, for their profile - and the rulesets it offers.
   */
  | { k: 'hello'; v: string; id: string | null; r: Ruleset[] }
  /** The host changed the setup of the next match. */
  | ({ k: 'setup' } & OnlineSetup)
  /**
   * The guest's own colours - its pick first - for the host to make the
   * match's pair from (see `onlineColors`).
   */
  | { k: 'colors'; colors: [string, string] }
  /** The host starts a match, on the ruleset both offered. */
  | ({ k: 'start'; n: number } & OnlineStart)
  /** A seat's input for tick `t`. */
  | ({ k: 'in'; n: number; t: number } & TickInput)
  /** The checksum of the match after tick `t` - see `matchChecksum`. */
  | { k: 'sum'; n: number; t: number; h: number }
  /** The other side leaves. */
  | { k: 'bye' };

/** The longest match a tick may belong to: an hour. */
const MAX_TICK = 60 * 60 * TICKS_PER_SEC;
/** The biggest seed or match number. */
const MAX_UINT32 = 2 ** 32 - 1;

/**
 * Reads what the other device sent - null for anything that is not a
 * message of this version. The other device is not trusted: every field is
 * checked, and what reaches the match is on the input grid.
 */
export function parseNetMessage(data: unknown): NetMessage | null {
  const value = typeof data === 'string' ? parseJson(data) : null;
  if (!isObject(value)) {
    return null;
  }
  switch (value['k']) {
    case 'hello': {
      const { v, id, r } = value;
      if (typeof v !== 'string') {
        return null;
      }
      // Whatever else it offers, every device runs the CPU's ruleset.
      const offers: Ruleset[] = Array.isArray(r)
        ? r.filter(isRuleset).filter((ruleset) => ruleset !== 'cpu')
        : [];
      return {
        k: 'hello',
        v,
        id: isPlayerId(id) ? id : null,
        r: ['cpu', ...new Set(offers)],
      };
    }
    case 'setup': {
      const setup = parseSetup(value);
      return setup === null ? null : { k: 'setup', ...setup };
    }
    case 'colors': {
      const colors = validColorPair(value['colors']);
      return colors === null ? null : { k: 'colors', colors };
    }
    case 'start': {
      const setup = parseSetup(value);
      const { seed, n, ruleset } = value;
      return setup === null ||
        !isUpTo(seed, MAX_UINT32) ||
        !isUpTo(n, MAX_UINT32) ||
        !isRuleset(ruleset)
        ? null
        : { k: 'start', n, ...setup, seed, ruleset };
    }
    case 'in': {
      const { t, n } = value;
      const steer = parsePair(value['steer'], 1);
      const drag =
        value['drag'] === null ? null : parsePair(value['drag'], 1e5);
      const boost = value['boost'];
      if (
        !isUpTo(t, MAX_TICK) ||
        !isUpTo(n, MAX_UINT32) ||
        steer === null ||
        (drag === null && value['drag'] !== null) ||
        typeof boost !== 'boolean'
      ) {
        return null;
      }
      return { k: 'in', n, t, steer, drag, boost };
    }
    case 'sum': {
      const { t, h, n } = value;
      return isUpTo(t, MAX_TICK) &&
        isUpTo(h, MAX_UINT32) &&
        isUpTo(n, MAX_UINT32)
        ? { k: 'sum', n, t, h }
        : null;
    }
    case 'bye':
      return { k: 'bye' };
    default:
      return null;
  }
}

function parseSetup(value: Record<string, unknown>): OnlineSetup | null {
  const levelId = value['levelId'];
  const colors = validColorPair(value['colors']);
  return isLevelId(levelId) && colors != null ? { levelId, colors } : null;
}

/** Two finite numbers no further from 0 than `limit`. */
function parsePair(value: unknown, limit: number): [number, number] | null {
  if (!Array.isArray(value) || value.length !== 2) {
    return null;
  }
  const [x, y] = value;
  return isWithin(x, limit) && isWithin(y, limit) ? [x, y] : null;
}

function isWithin(value: unknown, limit: number): value is number {
  return typeof value === 'number' && Math.abs(value) <= limit;
